Sample usage (to include in docs):

// create a stream with 1s grace on cancel and backoff retries
ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
stream := client.NewStream(ctx, WithStreamGrace(1*time.Second), WithReconnectPolicy("backoff"))
go func() {
  for msg := range stream.Messages() {
    // process
  }
}()
// when we want to stop but allow in-flight messages to finish:
cancel()
err := stream.Wait() // returns nil if graceful, context.Canceled if forced
